                command,
                prompt,
                await_response=await_response
            )
            return resp
        if command == CommandParser.SWAP_COMMAND:
            return self.swap_provider(prompt)

        if command == CommandParser.SAVE_COMMAND:
            # Automatically suggest a name if not explicitly set or on save
            if self.conversation_name == "Untitled Entity" and self.context.messages:
                self.suggest_and_set_title()
            return self.save_conversation(prompt)

        return self._send_to_llm(
            prompt+'\n(Return your message in a JSON format of {"message": "your message here"})',
            await_response=await_response
        )

    def _send_to_llm(
        self,
        prompt: str,
        await_response: bool = True
    ) -> str:
        """Send a normal conversation message to the LLM."""
        raw = self.llm.generate(
            prompt,
            await_response=await_response
        )
        try:
            cleanraw=raw[raw.find("{"):]
            if cleanraw[len(cleanraw)-1]=="\"":
                cleanraw=cleanraw+"}"
            parsed_response=json.loads(cleanraw)
            return parsed_response.get("message", "No message returned from LLM.")
        except json.JSONDecodeError:
            return raw + traceback.format_exc() + "\n[Error] LLM returned invalid JSON. Please ensure the LLM returns a valid JSON response."

    def _send_to_agent(
        self,
        command:str,
        prompt: str,
        await_response=True

